questions.question_text:
Find the side length of this square.
[tikz]
\begin{tikzpicture}[scale=0.8]
\draw (0,0) rectangle (3.0,3.0);
\node at (1.5,1.5) {$144\text{ cm}^{2}$};
\end{tikzpicture}
[/tikz]

questions.solution_text:
$\sqrt{144}$
$=12$
The side length is $12$ cm.
[tikz]
\begin{tikzpicture}[scale=0.8]
\draw (0,0) rectangle (3.0,3.0);
\node at (1.5,1.5) {$144\text{ cm}^{2}$};
\node[below] at (1.5,0) {$12\text{ cm}$};
\node[left] at (0,1.5) {$12\text{ cm}$};
\end{tikzpicture}
[/tikz]
